/**
 * Replays the real events the wraith-names contract emits (golden fixture generated by
 * wraith-names/tests/keeper_events.rs) through the keeper's actual decoder and
 * enumerator, so enumeration is tested against contract output rather than hand-made
 * events. The scenario: register "solo"; bulk_register alpha, bravo, charlie;
 * update alpha; release bravo.
 */
import { readFileSync } from 'fs';
import * as path from 'path';
import { xdr } from '@stellar/stellar-sdk';
import { describe, expect, it } from 'vitest';
import {
  DecodedEvent,
  EventPage,
  KeeperRpc,
  enumerateNames,
  nameHash,
  runKeeper,
} from './keeper-core';
import { decodeNameEvents } from './keeper-rpc';

interface FixtureEvent {
  ledger: number;
  topics: string[];
  value: string;
}

const fixture = JSON.parse(
  readFileSync(path.resolve(__dirname, 'fixtures', 'contract-events.json'), 'utf8'),
) as { events: FixtureEvent[] };

const scval = (hex: string) => xdr.ScVal.fromXDR(Buffer.from(hex, 'hex'));
const raw = fixture.events.map((e) => ({
  ledger: e.ledger,
  topic: e.topics.map(scval),
  value: scval(e.value),
}));
const decoded = decodeNameEvents(raw);

function rpcWith(events: DecodedEvent[], liveUntil: Record<string, number> = {}) {
  const extended: { name: string; to: number }[] = [];
  const ttl = new Map(Object.entries(liveUntil).map(([n, v]) => [nameHash(n), v] as const));
  const rpc: KeeperRpc = {
    getLatestLedger: async () => 200,
    getNameEvents: async (): Promise<EventPage> => ({ events, oldestLedger: 0, latestLedger: 200 }),
    getNameLiveUntil: async (h) => (ttl.has(h) ? (ttl.get(h) as number) : null),
    extendName: async (name, to) => {
      extended.push({ name, to });
      return `tx-${name}`;
    },
  };
  return { rpc, extended };
}

const opts = { threshold: 1000, extendTo: 5000, dryRun: false, startLedger: 1 };

describe('real contract events', () => {
  it('decodes name events and the aggregate bulk_reg, skipping unrelated events', () => {
    const kinds = decoded.map((e) => e.kind);
    expect(kinds.filter((k) => k === 'register')).toHaveLength(4); // solo + 3 bulk names
    expect(kinds.filter((k) => k === 'bulk')).toHaveLength(1);
    expect(kinds).toContain('update');
    expect(kinds).toContain('release');
    // metric events are in the fixture but are not keeper events
    expect(fixture.events.length).toBeGreaterThan(decoded.length);
  });

  it('bulk_register publishes a register event carrying the name for every bulk name', () => {
    const registered = decoded.filter((e) => e.kind === 'register').map((e) => (e as { name: string }).name);
    expect(registered.sort()).toEqual(['alpha', 'bravo', 'charlie', 'solo']);
  });

  it("the aggregate bulk_reg hashes equal the keeper's nameHash of each name", () => {
    const bulk = decoded.find((e) => e.kind === 'bulk') as { hashes: string[] };
    expect(bulk.hashes).toEqual(['alpha', 'bravo', 'charlie'].map(nameHash));
  });

  it('event-only enumeration recovers every live name, including bulk-registered ones', async () => {
    const { rpc } = rpcWith(decoded);
    expect(await enumerateNames(rpc, opts)).toEqual(['alpha', 'charlie', 'solo']);
  });

  it('runs end to end: extends the bulk-registered names that are near expiry', async () => {
    const { rpc, extended } = rpcWith(decoded, { solo: 5000, alpha: 300, charlie: 400 });
    const report = await runKeeper(rpc, opts);
    expect(report.total).toBe(3);
    expect(extended).toEqual([
      { name: 'alpha', to: 5000 },
      { name: 'charlie', to: 5000 },
    ]);
  });
});

describe('event-only enumeration cannot silently miss bulk-registered names', () => {
  // A contract (or version) whose bulk_register published only the aggregate bulk_reg
  // would leave those names invisible. Model that by dropping the per-name register
  // events of the bulk names, keeping the aggregate and everything else.
  const bulkNames = new Set(['alpha', 'bravo', 'charlie']);
  const withoutPerNameRegisters = decoded.filter(
    (e) => !(e.kind === 'register' && bulkNames.has(e.name)),
  );

  it('fails when a bulk hash has no recoverable name', async () => {
    const { rpc } = rpcWith(withoutPerNameRegisters);
    // alpha is recovered from its update event and bravo was released; charlie is not
    await expect(enumerateNames(rpc, opts)).rejects.toMatchObject({
      stage: 'enumeration',
      message: expect.stringContaining(nameHash('charlie')),
    });
    await expect(runKeeper(rpc, opts)).rejects.toMatchObject({ stage: 'enumeration' });
  });

  it('reports every unrecoverable hash when nothing else names them', async () => {
    const onlyBulk = decoded.filter((e) => e.kind === 'bulk');
    const { rpc } = rpcWith(onlyBulk);
    await expect(enumerateNames(rpc, opts)).rejects.toMatchObject({
      stage: 'enumeration',
      message: expect.stringContaining('3 name hash(es)'),
    });
  });

  it('succeeds once an index file supplies the missing name', async () => {
    const { rpc } = rpcWith(withoutPerNameRegisters);
    expect(await enumerateNames(rpc, { ...opts, indexedNames: ['charlie'] })).toEqual([
      'alpha',
      'charlie',
      'solo',
    ]);
  });

  it('does not require an index when every bulk hash was released', async () => {
    const released: DecodedEvent[] = [
      { ledger: 1, kind: 'bulk', hashes: [nameHash('gone')] },
      { ledger: 2, kind: 'release', name: 'gone' },
    ];
    const { rpc } = rpcWith(released);
    expect(await enumerateNames(rpc, opts)).toEqual([]);
  });
});
